const item = $input.item.json;

// The LLM's raw text output — adjust the source field if it's not `item.output`
// (e.g. could be `item.text` or the item itself if already a string).
let raw = item.output !== undefined ? item.output : item;

let parsed;
if (typeof raw === 'string') {
  parsed = JSON.parse(raw);
} else {
  parsed = raw;
}

return {
  json: {
    ...parsed,
    status: 'success'
  }
};
